INSERT OR IGNORE INTO v2_expression_context_versions(canonical_id,dataset_marker,context,reason) VALUES('legacy-108-en','2026-09-stage5-expansion-02-v1','A planning team has received a concerning forecast. Before choosing a backup plan, they must distinguish the forecast itself from the decision they make in response to it. The canonical sentence is a qualified next-step statement, not a weather-vocabulary exercise.','Clarifies the actors, observation-versus-decision contrast, and instructional purpose.');

INSERT OR IGNORE INTO v2_expression_context_versions(canonical_id,dataset_marker,context,reason) VALUES('legacy-156-ja','2026-09-stage5-expansion-02-v1','依頼を断るためではなく、誤解された意図を説明して関係を修復する場面。話者は相手を責めず、自分の境界と理由を明確にする。','Enough scenario information to interpret the unchanged personal-boundary expression as a no-blame repair.');

INSERT OR IGNORE INTO lesson_bundles(id,schema_version,payload_json,published_at) VALUES('curriculum-stage5-expansion-02-v1','CURRICULUM-STAGE5-EXPANSION-02','{"v":"CURRICULUM-STAGE5-EXPANSION-02","u":[["en-s1-l1","en",1,"chat","打招呼并开始简单交谈","能用基本问候开启并结束一段简短对话。",1,"published",15],["en-s1-l2","en",1,"social","道歉、感谢并自然回应","能在常见社交往来中道歉、致谢并作出自然回应。",2,"published",15],["en-s1-l3","en",1,"food","说出想吃喝的东西","能表达基本饮食需要并回应简单选择。",3,"published",15],["en-s1-l4","en",1,"help","提出一个简单请求","能用清楚、礼貌的方式请别人提供帮助。",4,"published",15],["en-s2-l1","en",2,"time","约定见面的时间","能询问时间并确认一项简单安排。",1,"published",15],["en-s2-l2","en",2,"shopping","询问价格并做选择","能在购物时问价、比较并说明选择。",2,"published",15],["en-s2-l3","en",2,"travel","问路并确认方向","能询问地点、理解并确认基本路线。",3,"published",15],["en-s2-l4","en",2,"home","描述日常生活安排","能谈论家中活动和每天的基本习惯。",4,"published",15],["en-s3-l1","en",3,"plans","讨论计划与期待","能说明计划变化、未来期待以及尚未确定的安排。",1,"published",15],["en-s3-l2","en",3,"health","描述今天的身体状态","能说出常见不适并回应基本健康建议。",2,"published",15],["en-s3-l3","en",3,"weather","根据天气调整计划","能描述天气并说明它对安排的影响。",3,"published",15],["en-s3-l4","en",3,"school","说明学习或工作任务","能谈论正在做的任务、期限和基本要求。",4,"published",15],["en-s4-l1","en",4,"feelings","解释感受和原因","能较具体地表达情绪并给出原因。",1,"published",15],["en-s4-l2","en",4,"social","在社交中表达界限","能礼貌回应私人问题、独处需要或提前离场。",2,"published",15],["en-s4-l3","en",4,"food","在餐厅完成点餐","能询问菜品、提出饮食要求并结账。",3,"published",15],["en-s4-l4","en",4,"hobbies","分享兴趣与偏好","能比较兴趣、说明偏好并继续相关交流。",4,"published",15],["en-s5-l1","en",5,"school","在限制下评估工作方案","能结合时间、证据和条件，评估工作方案的可行性并说明限制。",1,"published",15,"Evaluate a plan under constraints"],["en-s5-l2","en",5,"travel","应对行程不确定性与后备方案","能解释行程延误或变化，在不确定条件下协商替代安排和后备方案。",4,"published",15,"Handle itinerary uncertainty and contingencies"],["en-s5-l3","en",5,"help","升级服务或工作问题","能提供必要背景、说明问题边界，并提出有针对性的解决请求。",5,"published",15,"Escalate a service or workplace problem"],["en-s5-l4","en",5,"plans","用过去结果支持当前决定","能回顾原先预期和实际结果，评价过去选择并用其支持当前决定。",7,"published",15,"Relate past outcomes to current decisions"],["en-s6-l1","en",6,"school","陈述观点并用依据支持","能在较正式讨论中提出主张和理由。",1,"published",15],["en-s6-l2","en",6,"chat","澄清语气并讨论假设","能修正过强语气，并用假设说明不同可能。",2,"published",15],["en-s6-l3","en",6,"social","发出邀请并照顾对方选择","能提出活动邀请并给对方自然接受或拒绝的空间。",3,"published",15],["en-s6-l4","en",6,"plans","回顾经历并展望目标","能连接过去经验、当前判断与未来目标。",4,"published",15],["ja-s1-l1","ja",1,"chat","基本のあいさつを交わす","能用日语基本寒暄自然地开始和结束交流。",1,"published",15],["ja-s1-l2","ja",1,"social","お礼・謝罪・誘いに応じる","能在感谢、道歉和简单邀请中作出合适回应。",2,"published",15],["ja-s1-l3","ja",1,"food","食べたい物を伝える","能说出基本饮食需要并回应简单选择。",3,"published",15],["ja-s1-l4","ja",1,"help","短いお願いをする","能用日语常见礼貌形式提出简单请求。",4,"published",15],["ja-s2-l1","ja",2,"travel","助詞を使って行き先を伝える","能用基本助词说明目的地、方向和移动。",1,"published",15],["ja-s2-l2","ja",2,"home","家の中で頼み事を伝える","能在家中说明已做事项、提出请求并确认设备状态。",2,"published",15],["ja-s2-l3","ja",2,"time","時間を聞いて約束する","能询问时间、邀请对方并确认约定。",3,"published",15],["ja-s2-l4","ja",2,"shopping","数と量を確認して買う","能在购物时询问数量、价格并做出选择。",4,"published",15],["ja-s3-l1","ja",3,"chat","誤解を解き、言い方を整える","能回顾交流、补充不同看法并澄清误会。",1,"published",15],["ja-s3-l2","ja",3,"plans","経験とこれからの予定を話す","能连接过去经验、未来计划和暂未确定的安排。",2,"published",15],["ja-s3-l3","ja",3,"help","てくださいで具体的に頼む","能提出明确请求并根据语境调整礼貌程度。",3,"published",15],["ja-s3-l4","ja",3,"health","体調と症状を説明する","能描述身体状态、症状及持续情况。",4,"published",15],["ja-s4-l1","ja",4,"weather","理由を添えて予定を変える","能说明天气情况、原因及计划变化。",1,"published",15],["ja-s4-l2","ja",4,"plans","予定と予想のずれを説明する","能说明计划变化、结果与原先预期的差异。",2,"published",15],["ja-s4-l3","ja",4,"social","距離感に配慮して境界を伝える","能顾及关系与气氛，表达独处需要或婉拒。",3,"published",15],["ja-s4-l4","ja",4,"hobbies","好みを比べて会話を続ける","能比较爱好、说明偏好并追问细节。",4,"published",15],["ja-s5-l1","ja",5,"school","正式陈述判断与限制","能以较正式的日语依据证据作出有限度的判断，并说明可能性和限制。",1,"published",15,"限界を示しつつ、改まった場面で判断を述べる"],["ja-s5-l2","ja",5,"help","说明背景并体谅地请求","能先说明背景和理由，再以顾及对方感受的方式提出请求。",2,"published",15,"背景を説明し、相手に配慮して依頼する"],["ja-s5-l3","ja",5,"travel","用条件协商日程替代方案","能说明行程条件和限制，询问可行选项并协商替代安排。",4,"published",15,"条件を示して予定の代案を相談する"],["ja-s5-l4","ja",5,"feelings","委婉表达负担、担忧与保留","能提供背景并委婉表达负担、担忧和保留，避免把判断变成指责。",5,"published",15,"負担・懸念・遠慮をやわらかく伝える"],["ja-s6-l1","ja",6,"school","根拠を整理して説明する","能以较正式的日语组织观点、依据和结论。",1,"published",15],["ja-s6-l2","ja",6,"chat","確認しながら控えめに意見を述べる","能确认理解，并以保留或缓和方式表达判断。",2,"published",15],["ja-s6-l3","ja",6,"plans","経験を振り返り判断を伝える","能连接经历、反思和当前判断。",3,"published",15],["ja-s6-l4","ja",6,"social","誘いに応じ、予定変更を伝える","能回应邀请，并得体说明自己可能提前离场。",4,"published",15],["en-s2-l5","en",2,"shopping","在超市找货并结账","能询问商品位置、确认数量价格并完成支付。",5,"published",18],["en-s3-l5","en",3,"shopping","退货与换货","能说明商品问题、提出退款或换货并确认处理条件。",5,"published",18],["en-s3-l6","en",3,"health","在药房或诊所说明症状","能描述症状、持续时间和严重度并理解基本建议。",6,"published",18],["en-s3-l7","en",3,"time","预约、取消与改期","能预约、确认、取消并协商替代时间。",7,"published",18],["en-s3-l8","en",3,"help","处理手机与网络问题","能描述连接问题并执行、确认排障步骤。",8,"published",18],["en-s3-l9","en",3,"school","职场任务、排班与反馈","能汇报进展、协调班次并回应反馈。",9,"published",18],["en-s4-l5","en",4,"home","租房、报修与房东沟通","能说明住房问题、请求维修并确认费用和时间。",5,"published",18],["en-s4-l6","en",4,"travel","入住酒店并处理住宿问题","能办理入住、询问设施并处理房间问题。",6,"published",18],["ja-s2-l5","ja",2,"shopping","スーパーで商品を探して会計する","能询问位置、数量、价格并完成超市支付。",5,"published",18],["ja-s2-l6","ja",2,"food","店で注文し、希望を伝える","能点餐、说明饮食限制并结账。",6,"published",18],["ja-s3-l5","ja",3,"shopping","返品・交換を相談する","能说明商品问题并协商退换条件。",5,"published",18],["ja-s3-l6","ja",3,"health","薬局・病院で症状を説明する","能说明症状、程度与持续时间并理解建议。",6,"published",18],["ja-s3-l7","ja",3,"help","スマホ・通信の問題を伝える","能描述连接问题并确认排障步骤。",7,"published",18],["ja-s3-l8","ja",3,"school","職場で報告・連絡・相談する","能汇报、联络和商量并保持合适礼貌度。",8,"published",18],["ja-s4-l5","ja",4,"home","賃貸・修理について相談する","能向房东或管理方报修并确认费用与时间。",5,"published",18],["ja-s4-l6","ja",4,"travel","宿泊手続きと部屋の問題に対応する","能办理入住、询问设施并处理房间问题。",6,"published",18],["en-s5-02-tradeoffs","en",5,"plans","比较方案与取舍","能依据成本、人员配置和风险比较方案，说明取舍并提出有理由的选择。",2,"published",15,"Compare alternatives and trade-offs"],["en-s5-03-consensus","en",5,"school","协商优先事项并达成共识","能说明优先事项和资源冲突，礼貌表达不同意见，并协商出共同接受的分配方案。",3,"published",15,"Negotiate priorities and reach consensus"],["en-s5-06-repair","en",5,"chat","澄清信息并修复误解","能区分事实、推断与意图，通过澄清、换言和不归责表达修复误解。",6,"published",15,"Clarify information and repair a misunderstanding"],["en-s5-08-reporting","en",5,"school","报告信息并区分观察与推断","能在报告中准确陈述观察，标明推断和假设，并说明证据限制。",8,"published",15,"Report information and distinguish observation from inference"],["ja-s5-03-formal-role","ja",5,"travel","在明确服务角色中选择敬语与谦让语","能在顾客与工作人员角色明确的场景中，用「おっしゃる」描述顾客发言，并用「いたす」描述己方行动。",3,"published",15,"接客場面で尊敬語と謙譲語を選ぶ"],["ja-s5-06-repair","ja",5,"chat","不责怪对方地修复误解","能区分事实、推测和意图，以不归责的方式澄清并修复误解。",6,"published",15,"相手を責めずに誤解を解く"],["ja-s5-07-consensus","ja",5,"plans","比较优先事项与取舍并达成共识","能比较优先事项和资源取舍，提出经过缓和的规范性判断，并达成分配共识。",7,"published",15,"優先事項とトレードオフを比べて合意する"],["ja-s5-08-benefit","ja",5,"help","判断受益方向并选择授受表达","能判断行动者与受益者的方向，并依据关系和场景选择合适的授受表达。",8,"published",15,"恩恵の向きを捉えて授受表現を選ぶ"]],"p":[["en-s1-l2","en-s1-l1"],["en-s1-l3","en-s1-l2"],["en-s1-l4","en-s1-l3"],["en-s2-l1","en-s1-l4"],["en-s2-l2","en-s2-l1"],["en-s2-l3","en-s2-l2"],["en-s2-l4","en-s2-l3"],["en-s3-l1","en-s2-l5"],["en-s3-l2","en-s3-l1"],["en-s3-l3","en-s3-l2"],["en-s3-l4","en-s3-l3"],["en-s4-l1","en-s3-l9"],["en-s4-l2","en-s4-l1"],["en-s4-l3","en-s4-l2"],["en-s4-l4","en-s4-l3"],["en-s6-l2","en-s6-l1"],["en-s6-l3","en-s6-l2"],["en-s6-l4","en-s6-l3"],["ja-s1-l2","ja-s1-l1"],["ja-s1-l3","ja-s1-l2"],["ja-s1-l4","ja-s1-l3"],["ja-s2-l1","ja-s1-l4"],["ja-s2-l2","ja-s2-l1"],["ja-s2-l3","ja-s2-l2"],["ja-s2-l4","ja-s2-l3"],["ja-s3-l1","ja-s2-l6"],["ja-s3-l2","ja-s3-l1"],["ja-s3-l3","ja-s3-l2"],["ja-s3-l4","ja-s3-l3"],["ja-s4-l1","ja-s3-l8"],["ja-s4-l2","ja-s4-l1"],["ja-s4-l3","ja-s4-l2"],["ja-s4-l4","ja-s4-l3"],["ja-s6-l2","ja-s6-l1"],["ja-s6-l3","ja-s6-l2"],["ja-s6-l4","ja-s6-l3"],["en-s2-l5","en-s2-l4"],["en-s3-l5","en-s3-l4"],["en-s3-l6","en-s3-l5"],["en-s3-l7","en-s3-l6"],["en-s3-l8","en-s3-l7"],["en-s3-l9","en-s3-l8"],["en-s4-l5","en-s4-l4"],["en-s4-l6","en-s4-l5"],["ja-s2-l5","ja-s2-l4"],["ja-s2-l6","ja-s2-l5"],["ja-s3-l5","ja-s3-l4"],["ja-s3-l6","ja-s3-l5"],["ja-s3-l7","ja-s3-l6"],["ja-s3-l8","ja-s3-l7"],["ja-s4-l5","ja-s4-l4"],["j