it","vocabulary","ja-c-527","support",8,0,"REVIEW"],["ja-s5-08-benefit","grammar","ja-te-morau","support",1,0,"REVIEW"],["ja-s5-08-benefit","grammar","ja-te-kureru","support",2,0,"REVIEW"],["ja-s5-08-benefit","grammar","ja-te-itadaku","support",3,0,"REVIEW"],["ja-s5-08-benefit","expression","legacy-165-ja","support",1,0,"REVIEW"],["ja-s5-08-benefit","expression","legacy-164-ja","support",2,0,"REVIEW"],["ja-s5-08-benefit","expression","35e1b-ja-x-alternative-repair-expr","support",3,0,"REVIEW"],["ja-s5-08-benefit","expression","35e1b-ja-x-hotel-quiet-room-expr","support",4,0,"REVIEW"]],"e":[["IELTS","5.0","en-s1-l2",1],["IELTS","5.0","en-s1-l4",1],["IELTS","5.0","en-s2-l2",1],["IELTS","5.0","en-s2-l3",1],["IELTS","5.0","en-s2-l4",1],["IELTS","5.0","en-s4-l2",1],["IELTS","5.5","en-s1-l2",1],["IELTS","5.5","en-s3-l2",1],["IELTS","5.5","en-s5-l4",1],["IELTS","5.5","en-s6-l3",1],["IELTS","6.0","en-s1-l4",2],["IELTS","6.0","en-s5-l1",1],["IELTS","6.0","en-s6-l2",2],["IELTS","6.5","en-s3-l1",1],["IELTS","6.5","en-s3-l3",1],["IELTS","6.5","en-s5-l1",3],["IELTS","6.5","en-s5-l4",1],["IELTS","7.0+","en-s6-l1",3],["JLPT","N1","ja-s6-l1",3],["JLPT","N2","ja-s5-l1",2],["JLPT","N2","ja-s6-l1",1],["JLPT","N3","ja-s3-l3",1],["JLPT","N3","ja-s5-l1",3],["JLPT","N3","ja-s5-l2",1],["JLPT","N3","ja-s6-l1",1],["JLPT","N3","ja-s6-l2",1],["JLPT","N4","ja-s2-l2",2],["JLPT","N4","ja-s2-l3",1],["JLPT","N4","ja-s3-l2",2],["JLPT","N4","ja-s3-l4",1],["JLPT","N4","ja-s4-l1",2],["JLPT","N4","ja-s4-l3",3],["JLPT","N5","ja-s1-l1",1],["JLPT","N5","ja-s1-l2",1],["JLPT","N5","ja-s1-l3",3],["JLPT","N5","ja-s2-l2",1],["JLPT","N5","ja-s5-l3",1],["JLPT","N5","ja-s6-l4",1]],"a":[{"asset_id":"2026-09-stage5-expansion-02-v1-dialogue-en3","lesson_id":"en-s5-03-consensus","kind":"dialogue","language":"en","outcome":"Negotiate priorities/resources toward consensus.","register_note":"Neutral-professional peer discussion. Disagreement is acknowledged before a concern; may and the final allocation keep the negotiation collaborative.","turns":[{"turn_number":1,"speaker":"Maya","role":"project lead","text":"Our first priority is protecting the testing time.","translation_zh":"我们的首要事项是保证测试时间。"},{"turn_number":2,"speaker":"Daniel","role":"project lead","text":"We need the same two engineers for testing and the client demo, so we cannot fully staff both.","translation_zh":"测试和客户演示都需要同样的两名工程师，因此两边无法同时配足人手。"},{"turn_number":3,"speaker":"Maya","role":"project lead","text":"I see your point, but I have a concern: cutting the test scope may create more risk.","translation_zh":"我明白你的意思，但我有一个担忧：缩小测试范围可能会带来更大风险。"},{"turn_number":4,"speaker":"Daniel","role":"project lead","text":"What if we commit one engineer to testing and one to the demo?","translation_zh":"我们把一名工程师投入测试，另一名投入演示，怎么样？"},{"turn_number":5,"speaker":"Maya","role":"project lead","text":"That may be feasible, even if the demo has a smaller scope.","translation_zh":"即使演示的范围缩小一些，这个方案也可能可行。"},{"turn_number":6,"speaker":"Daniel","role":"project lead","text":"Agreed. We have a consensus: we''ll keep one engineer on testing and assign one to the demo.","translation_zh":"同意。我们达成共识了：一名工程师继续负责测试，另一名分配给演示。"}]},{"asset_id":"2026-09-stage5-expansion-02-v1-dialogue-ja3","lesson_id":"ja-s5-03-formal-role","kind":"dialogue","language":"ja","outcome":"Use specific honorific/humble choices in a defined service role.","register_note":"Hotel customer/staff roles are fixed. おっしゃる describes the customer saying something; いたす describes the staff side doing something. No other honorific or humble verb is taught as authority.","turns":[{"turn_number":1,"speaker":"佐藤","role":"customer","text":"予約のチェックアウト日を十七日に変更したいです。","translation_zh":"我想把预订的退房日期改到十七日。"},{"turn_number":2,"speaker":"田中","role":"hotel front-desk staff","text":"承知しました。空室状況を確認します。","translation_zh":"明白了。我确认一下空房情况。"},{"turn_number":3,"speaker":"田中","role":"hotel front-desk staff","text":"空室がありますので、変更の手続きをいたします。","translation_zh":"有空房，因此我为您办理变更手续。"},{"turn_number":4,"speaker":"佐藤","role":"customer","text":"はい。部屋の種類は同じでお願いします。","translation_zh":"好的。房型请保持不变。"},{"turn_number":5,"speaker":"佐藤","role":"customer","text":"あ、すみません。十七日ではなく、十八日です。","translation_zh":"啊，对不起。不是十七日，是十八日。"},{"turn_number":6,"speaker":"田中","role":"hotel front-desk staff","text":"先ほど十七日とおっしゃいましたが、十八日ですね。\nこちらで変更いたします。少々お待ちください。","translation_zh":"您刚才说的是十七日，不过现在确认是十八日，对吧？我们这边为您办理变更，请稍等。"}]},{"asset_id":"2026-09-stage5-expansion-02-v1-dialogue-ja7","lesson_id":"ja-s5-07-consensus","kind":"dialogue","language":"ja","outcome":"Compare priorities/trade-offs and reach agreement.","register_note":"Neutral-formal peer planning. トレードオフ is appropriate business vocabulary here and should receive a Chinese gloss at first exposure. べき is softened by と思います and is used for a reasoned priority, not a command.","turns":[{"turn_number":1,"speaker":"森","role":"team member","text":"今回の優先事項は、品質確認の時間を確保することです。","translation_zh":"这次的优先事项是确保质量检查的时间。"},{"turn_number":2,"speaker":"林","role":"team member","text":"ただ、人員が限られているので、納期に間に合わない懸念があります。","translation_zh":"不过，由于人员有限，我担心可能赶不上期限。"},{"turn_number":3,"speaker":"森","role":"team member","text":"確かに、速さと正確さの間にはトレードオフがあります。急げば急ぐほど、確認の時間が減ります。","translation_zh":"的确，速度和准确性之间存在取舍。越着急，检查时间就越少。"},{"turn_number":4,"speaker":"林","role":"team member","text":"では、二人を品質確認に、一人を進行管理に配分するのはどうでしょうか。","translation_zh":"那么，把两人分配到质量检查，一人分配到进度管理，怎么样？"},{"turn_number":5,"speaker":"森","role":"team member","text":"そうですね。ただ、重要な確認項目を先に扱うべきだと思います。","translation_zh":"可以。不过，我认为应该先处理重要的检查项目。"},{"turn_number":6,"speaker":"林","role":"team member","text":"賛成です。その配分で合意しましょう。","translation_zh":"赞成。我们就按这个分配方案达成一致吧。"}]},{"asset_id":"2026-09-stage5-expansion-02-v1-prompt-en6","lesson_id":"en-s5-06-repair","kind":"reuse_prompt","canonical_ids":["35e1b-en-d-misunderstanding-tone-expr"],"decision":"Reuse; do not duplicate.","adaptation_prompt_layer":["Label the observable wording and the inferred blame separately.","Rephrase the intent with the selected not-that frame.","Choose a non-blaming repair move, then explain why it repairs tone rather than facts."]},{"asset_id":"2026-09-stage5-expansion-02-v1-prompt-ja6","lesson_id":"ja-s5-06-repair","kind":"reuse_prompt","canonical_ids":["35e1b-ja-d-misunderstanding-tone-expr"],"decision":"Reuse; do not duplicate.","adaptation_prompt_layer":["事実として聞こえた表現、相手の推測、話者の意図を分ける。","「わけではない」と「ようだ」を使う箇所を選ばせる。","責めない言い換えを作り、元の意図が変わっていないことを確認する。"]},{"asset_id":"2026-09-stage5-expansion-02-v1-prompt-ja8","lesson_id":"ja-s5-08-benefit","kind":"reuse_prompt","canonical_ids":["legacy-165-ja","legacy-164-ja","35e1b-ja-x-alternative-repair-expr","35e1b-ja-x-hotel-quiet-room-expr"],"decision":"Reuse the existing expression set; do not create a duplicate dialogue.","adaptation_prompt_layer":["For each sentence, identify who performs the action and who benefits.","Contrast てもらう with the already-published てくれる model using selection/recall, not a new canonical sentence.","Order the four expressions by relationship and service-register distance; do not treat いただく as a different benefit direction."]},{"asset_id":"2026-09-stage5-expansion-02-v1-scenario-en2","lesson_id":"en-s5-02-tradeoffs","kind":"scenario","scenario":"A delivery team must choose between an express plan that costs more and a standard plan that needs fewer staff but carries a delay risk. Compare both options against cost, staffing, and risk, then recommend one with a stated limitation."},{"asset_id":"2026-09-stage5-expansion-02-v1-scenario-en8","lesson_id":"en-s5-08-reporting","kind":"scenario","scenario":"A report records that a shipment arrived two days late and that its seal was intact. The writer suspects a scheduling error, but has no direct evidence of the cause. Label the two observations and the one inference before revising the report."}]}','2026-09-15T00:00:00Z');
